CREATE TABLE `achievement_rewards` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `achievement_id` bigint NOT NULL,
  `amount` bigint DEFAULT NULL,
  `reference_code` varchar(64) DEFAULT NULL,
  `reward_type` enum('BADGE','COIN','EXPERIENCE') NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_achievement_rewards_achievement_id` (`achievement_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `achievements` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `category` enum('COLLECTION','EVENT','FARM') NOT NULL,
  `code` varchar(64) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `enabled` bit(1) NOT NULL,
  `metric` enum('MAX_OWNED_COUNT_PER_TYPE','ONLY_START_END_PLACED','OWNED_TYPE_COUNT','PLACED_ANIMAL_COUNT','PRE_REGISTRATION_CONVERTED') NOT NULL,
  `metric_param` varchar(32) DEFAULT NULL,
  `target_value` bigint NOT NULL,
  `title` varchar(100) NOT NULL,
  `achieved_image_key` varchar(255) DEFAULT NULL,
  `hidden` bit(1) NOT NULL,
  `unachieved_image_key` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_achievements_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `animals` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `capture_id` bigint NOT NULL,
  `floor_num` int DEFAULT NULL,
  `slot_num` int DEFAULT NULL,
  `space_id` bigint DEFAULT NULL,
  `version` bigint NOT NULL,
  `rest_ends_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_animals_capture_id` (`capture_id`),
  KEY `idx_animals_space_id_floor_num_slot_num` (`space_id`,`floor_num`,`slot_num`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `anonymous_devices` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `ai_generated_at` datetime(6) DEFAULT NULL,
  `ai_generated_used` bit(1) DEFAULT NULL,
  `device_token` varchar(255) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_anonymous_devices_device_token` (`device_token`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `badges` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `code` varchar(64) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `image_key` varchar(255) DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_badges_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

