CREATE TABLE `battles` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `ended_at` datetime(6) DEFAULT NULL,
  `gym_leader_id` bigint NOT NULL,
  `result` enum('LOSE','WIN') DEFAULT NULL,
  `started_at` datetime(6) NOT NULL,
  `status` enum('ABANDONED','FINISHED','IN_PROGRESS') NOT NULL,
  `user_id` bigint NOT NULL,
  `bar_position` int NOT NULL,
  `client_request_id` varchar(36) NOT NULL,
  `final_expires_at` datetime(6) DEFAULT NULL,
  `final_move_distance` int DEFAULT NULL,
  `final_tap_count` int DEFAULT NULL,
  `last_action_at` datetime(6) DEFAULT NULL,
  `final_points` int DEFAULT NULL,
  `final_ready_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_battles_user_id_client_request_id` (`user_id`,`client_request_id`),
  KEY `idx_battles_user_id_started_at` (`user_id`,`started_at` DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

