CREATE TABLE `gym_leader_clears` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `badge_code` varchar(64) NOT NULL,
  `battle_id` bigint NOT NULL,
  `coins_after` bigint NOT NULL,
  `experience_after` bigint NOT NULL,
  `experience_reward` bigint NOT NULL,
  `gym_leader_coin_reward` bigint NOT NULL,
  `gym_leader_id` bigint NOT NULL,
  `level_after` int NOT NULL,
  `level_before` int NOT NULL,
  `level_up_coin_reward` bigint NOT NULL,
  `required_experience_for_next_level` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_gym_leader_clears_user_leader` (`user_id`,`gym_leader_id`),
  UNIQUE KEY `uk_gym_leader_clears_battle_id` (`battle_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `gym_leaders` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `badge_code` varchar(64) NOT NULL,
  `challenge_order` int NOT NULL,
  `code` varchar(64) NOT NULL,
  `image_key` varchar(255) DEFAULT NULL,
  `name` varchar(50) NOT NULL,
  `thumbnail_key` varchar(255) DEFAULT NULL,
  `difficulty` varchar(255) DEFAULT NULL,
  `leader_description` varchar(255) DEFAULT NULL,
  `leader_type` enum('GROUND','SEA','SKY','SPACE','MIXED') DEFAULT NULL,
  `tip_description` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_gym_leaders_code` (`code`),
  UNIQUE KEY `uk_gym_leaders_challenge_order` (`challenge_order`),
  UNIQUE KEY `uk_gym_leaders_badge_code` (`badge_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `pre_registration_coupon_recipients` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `capture_id` bigint DEFAULT NULL,
  `converted_at` datetime(6) DEFAULT NULL,
  `coupon_id` bigint NOT NULL,
  `pre_registration_id` bigint NOT NULL,
  `user_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pre_registration_coupon_recipients_coupon_id` (`coupon_id`),
  UNIQUE KEY `uk_pre_registration_coupon_recipients_pre_registration_id` (`pre_registration_id`),
  UNIQUE KEY `uk_pre_registration_coupon_recipients_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `pre_registrations` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `characterization_id` bigint NOT NULL,
  `phone_number_encrypted` varchar(512) NOT NULL,
  `phone_number_hash` varchar(128) NOT NULL,
  `required_consent` bit(1) NOT NULL,
  `status` enum('CANCELED','REGISTERED') NOT NULL,
  `message_sent_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pre_registrations_phone_number_hash` (`phone_number_hash`),
  KEY `idx_pre_registrations_phone_number_hash` (`phone_number_hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `user_achievements` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `achievement_id` bigint NOT NULL,
  `reward_claimed_at` datetime(6) DEFAULT NULL,
  `user_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_achievements_user_achievement` (`user_id`,`achievement_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `user_badges` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `badge_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_badges_user_badge` (`user_id`,`badge_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `users` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `coins` bigint NOT NULL,
  `email` varchar(255) DEFAULT NULL,
  `experience` bigint NOT NULL,
  `level` int NOT NULL,
  `nickname` varchar(255) DEFAULT NULL,
  `provider` enum('APPLE','KAKAO','NAVER') NOT NULL,
  `provider_id` varchar(255) NOT NULL,
  `marketing_agreed_at` datetime(6) DEFAULT NULL,
  `required_terms_agreed_at` datetime(6) DEFAULT NULL,
  `service_quality_agreed_at` datetime(6) DEFAULT NULL,
  `withdrawal_reason` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_users_provider_email` (`provider`,`email`),
  UNIQUE KEY `uk_users_nickname` (`nickname`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

